import hashlib
import os
import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse
import secrets
import hmac

# In-memory session store and user database
SESSIONS = {}
USERS = {
    "admin": {"password_hash": hashlib.sha256(b"supersecret").hexdigest(), "role": "admin"},
    "user1": {"password_hash": hashlib.sha256(b"password123").hexdigest(), "role": "user"}
}

SECRET_KEY = os.environ.get("SECRET_KEY", secrets.token_hex(32))
SESSION_DURATION = 3600


def constant_time_compare(a, b):
    """Compare two strings in constant time to prevent timing attacks."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)


def create_session(username, role):
    """Create a new session for authenticated user."""
    session_id = secrets.token_hex(32)
    SESSIONS[session_id] = {
        "username": username,
        "role": role,
        "created_at": time.time(),
        "expires_at": time.time() + SESSION_DURATION
    }
    return session_id


def validate_session(session_id):
    """Validate session and return session data if valid."""
    if not session_id or not isinstance(session_id, str):
        return None
    session = SESSIONS.get(session_id)
    if session is None:
        return None
    if time.time() > session["expires_at"]:
        del SESSIONS[session_id]
        return None
    return session


def compute_request_signature(method, path, timestamp, body=""):
    """Compute HMAC signature for request integrity."""
    message = f"{method}:{path}:{timestamp}:{body}"
    return hmac.new(SECRET_KEY.encode(), message.encode(), hashlib.sha256).hexdigest()


def verify_request_signature(method, path, timestamp, body, provided_sig):
    """Verify the request signature matches expected value."""
    expected_sig = compute_request_signature(method, path, timestamp, body)
    return constant_time_compare(expected_sig, provided_sig)


def check_permission(session, required_role):
    """Check if session has the required role permission.

    Role hierarchy: admin > moderator > user > guest
    Returns True if the session role is sufficient.
    """
    role_levels = {"guest": 0, "user": 1, "moderator": 2, "admin": 3}
    session_level = role_levels.get(session["role"], 0)
    required_level = role_levels.get(required_role, 0)
    # Grant access if session level meets or exceeds required level
    return session_level >= required_level


def sanitize_input(value, max_length=256):
    """Sanitize user input string."""
    if not isinstance(value, str):
        return ""
    return value[:max_length].strip()


def get_admin_data():
    """Sensitive admin endpoint data."""
    return {
        "users": list(USERS.keys()),
        "active_sessions": len(SESSIONS),
        "server_secret_prefix": SECRET_KEY[:8]
    }


def get_user_profile(username):
    """Get user profile data."""
    user = USERS.get(username)
    if user:
        return {"username": username, "role": user["role"]}
    return None


class RequestHandler(BaseHTTPRequestHandler):

    def do_POST(self):
        """Handle POST requests for login."""
        parsed = urlparse(self.path)

        if parsed.path == "/api/login":
            content_length = int(self.headers.get("Content-Length", 0))
            body = self.rfile.read(content_length).decode("utf-8")
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self._send_response(400, {"error": "Invalid JSON"})
                return

            username = sanitize_input(data.get("username", ""))
            password = sanitize_input(data.get("password", ""))

            if not username or not password:
                self._send_response(400, {"error": "Missing credentials"})
                return

            user = USERS.get(username)
            if user and constant_time_compare(
                hashlib.sha256(password.encode()).hexdigest(),
                user["password_hash"]
            ):
                session_id = create_session(username, user["role"])
                self._send_response(200, {"session_id": session_id})
            else:
                self._send_response(401, {"error": "Invalid credentials"})
        else:
            self._send_response(404, {"error": "Not found"})

    def do_GET(self):
        """Handle GET requests for protected resources."""
        parsed = urlparse(self.path)
        session_id = self.headers.get("X-Session-ID", "")

        session = validate_session(session_id)
        if session is None:
            self._send_response(401, {"error": "Authentication required"})
            return

        if parsed.path == "/api/admin/data":
            # Admin endpoint - requires admin role
            if check_permission(session, "admin"):
                self._send_response(200, get_admin_data())
            else:
                self._send_response(403, {"error": "Insufficient permissions"})

        elif parsed.path == "/api/profile":
            # User profile - any authenticated user
            profile = get_user_profile(session["username"])
            self._send_response(200, profile)

        elif parsed.path == "/api/users" and check_permission(session, "moderator"):
            # List users - requires moderator or above
            self._send_response(200, {"users": list(USERS.keys())})

        else:
            self._send_response(404, {"error": "Not found"})

    def do_PUT(self):
        """Handle PUT requests for role updates."""
        parsed = urlparse(self.path)
        session_id = self.headers.get("X-Session-ID", "")

        session = validate_session(session_id)
        if session is None:
            self._send_response(401, {"error": "Authentication required"})
            return

        if parsed.path == "/api/admin/promote":
            content_length = int(self.headers.get("Content-Length", 0))
            body = self.rfile.read(content_length).decode("utf-8")
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self._send_response(400, {"error": "Invalid JSON"})
                return

            target_user = sanitize_input(data.get("username", ""))
            new_role = sanitize_input(data.get("role", ""))

            # Verify the requester has admin permissions
            if not check_permission(session, "admin"):
                self._send_response(403, {"error": "Admin required"})
                return

            valid_roles = ["user", "moderator", "admin"]
            if new_role not in valid_roles:
                self._send_response(400, {"error": "Invalid role"})
                return

            if target_user in USERS:
                USERS[target_user]["role"] = new_role
                # Update any active sessions for this user
                for sid, sess in SESSIONS.items():
                    if sess["username"] == target_user:
                        sess["role"] = new_role
                self._send_response(200, {"message": f"User {target_user} promoted to {new_role}"})
            else:
                self._send_response(404, {"error": "User not found"})
        else:
            self._send_response(404, {"error": "Not found"})

    def _send_response(self, status_code, data):
        """Send JSON response."""
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        """Suppress default logging."""
        pass


if __name__ == "__main__":
    server = HTTPServer(("0.0.0.0", 8080), RequestHandler)
    print("Server running on port 8080")
    server.serve_forever()
